"""Money arithmetic for invoices."""
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")


def line_total(qty, unit_price):
    """Return the line amount in cents, rounded half-up."""
    amount = Decimal(str(qty)) * Decimal(str(unit_price))
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


def total(lines):
    """Return the invoice total as the sum of the rounded line amounts."""
    return sum(
        (line_total(line["qty"], line["unit_price"]) for line in lines),
        Decimal("0.00"),
    )

import unittest

from invoicer.export import to_csv


class TestExport(unittest.TestCase):
    def test_header_and_rows(self):
        invoice = {
            "client": "Acme",
            "lines": [
                {"item": "Hosting", "qty": "3", "unit_price": "1.115"},
                {"item": "Support", "qty": "1", "unit_price": "2.675"},
            ],
        }
        self.assertEqual(
            to_csv(invoice),
            "item,qty,unit_price,line_total\n"
            "Hosting,3,1.115,3.35\n"
            "Support,1,2.675,2.68\n",
        )

    def test_quotes_items_containing_delimiters(self):
        invoice = {
            "client": "Brightwell",
            "lines": [
                {"item": "Design, phase 2", "qty": "2", "unit_price": "410.125"},
                {"item": 'Review "final"', "qty": "1", "unit_price": "99.995"},
            ],
        }
        self.assertEqual(
            to_csv(invoice),
            "item,qty,unit_price,line_total\n"
            '"Design, phase 2",2,410.125,820.25\n'
            '"Review ""final""",1,99.995,100.00\n',
        )

    def test_line_total_always_has_two_decimals(self):
        invoice = {
            "client": "Corvid Ltd",
            "lines": [{"item": "Licences", "qty": "12", "unit_price": "8.3333"}],
        }
        rows = to_csv(invoice).splitlines()
        self.assertEqual(rows[1], "Licences,12,8.3333,100.00")


if __name__ == "__main__":
    unittest.main()

import contextlib
import io
import json
import os
import tempfile
import unittest

from invoicer.cli import main

INVOICE = {
    "client": "Acme",
    "lines": [{"item": "Support", "qty": "1", "unit_price": "2.675"}],
}


class TestCli(unittest.TestCase):
    def setUp(self):
        fd, self.path = tempfile.mkstemp(suffix=".json")
        with os.fdopen(fd, "w") as f:
            json.dump(INVOICE, f)

    def tearDown(self):
        os.unlink(self.path)

    def run_cli(self, *args):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            main([self.path, *args])
        return out.getvalue()

    def test_default_currency_is_eur(self):
        self.assertEqual(self.run_cli(), "Acme: \u20ac2.68\n")

    def test_usd(self):
        self.assertEqual(self.run_cli("--currency", "USD"), "Acme: $2.68\n")

    def test_gbp(self):
        self.assertEqual(self.run_cli("--currency", "GBP"), "Acme: \u00a32.68\n")

    def test_unknown_currency_is_an_error(self):
        err = io.StringIO()
        with contextlib.redirect_stderr(err):
            with self.assertRaises(SystemExit) as raised:
                self.run_cli("--currency", "CHF")
        self.assertEqual(raised.exception.code, 2)
        self.assertIn("invalid choice", err.getvalue())


if __name__ == "__main__":
    unittest.main()

